const upsertProviderPlanCapacity = `-- name: UpsertProviderPlanCapacity :one
INSERT INTO provider_plan_capacity (
    owner_id,
    provider,
    known,
    remaining_permille,
    reserve_permille,
    window_ends_at,
    observed_at,
    source
)
VALUES (
    $1,
    $2,
    $3,
    $4,
    $5,
    $6,
    $7,
    $8
)
ON CONFLICT (owner_id, provider)
DO UPDATE SET
    known = EXCLUDED.known,
    remaining_permille = EXCLUDED.remaining_permille,
    reserve_permille = EXCLUDED.reserve_permille,
    window_ends_at = EXCLUDED.window_ends_at,
    observed_at = EXCLUDED.observed_at,
    source = EXCLUDED.source,
    updated_at = now()
RETURNING owner_id, provider, known, remaining_permille, reserve_permille, reserved_inflight_permille, window_ends_at, observed_at, source, updated_at
`

type UpsertProviderPlanCapacityParams struct {
	OwnerID           pgtype.UUID        `json:"owner_id"`
	Provider          string             `json:"provider"`
	Known             bool               `json:"known"`
	RemainingPermille int32              `json:"remaining_permille"`
	ReservePermille   int32              `json:"reserve_permille"`
	WindowEndsAt      pgtype.Timestamptz `json:"window_ends_at"`
	ObservedAt        pgtype.Timestamptz `json:"observed_at"`
	Source            string             `json:"source"`
}

func (q *Queries) UpsertProviderPlanCapacity(ctx context.Context, arg UpsertProviderPlanCapacityParams) (ProviderPlanCapacity, error) {
	row := q.db.QueryRow(ctx, upsertProviderPlanCapacity,
		arg.OwnerID,
		arg.Provider,
		arg.Known,
		arg.RemainingPermille,
		arg.ReservePermille,
		arg.WindowEndsAt,
		arg.ObservedAt,
		arg.Source,
	)
	var i ProviderPlanCapacity
	err := row.Scan(
		&i.OwnerID,
		&i.Provider,
		&i.Known,
		&i.RemainingPermille,
		&i.ReservePermille,
		&i.ReservedInflightPermille,
		&i.WindowEndsAt,
		&i.ObservedAt,
		&i.Source,
		&i.UpdatedAt,
	)
	return i, err
}
